#dsh-tobottom-keep{
        position:fixed;right:10px;bottom:10px;z-index:2147483000;
        width:34px;height:34px;padding:0;border-radius:50%;cursor:pointer;
        border:1px solid color-mix(in srgb, currentColor 22%, transparent);
        background:color-mix(in srgb, currentColor 10%, transparent);
        color:inherit;display:flex;align-items:center;justify-content:center;
        opacity:.85;transition:opacity .15s ease, bottom .15s ease;
      }

autohide:
(function () {
  // 发送后自动收起输入框：靠"输入内容被清空"来判定（发送成功的可靠信号）
  var last = null;
  function mode() { return document.documentElement.getAttribute('data-dsh-composer'); }
  function seat() { return document.querySelector('.wSkVaW_composerSeat'); }
  function input() {
    var s = seat(); if (!s) return null;
    return s.querySelector('textarea,[contenteditable="true"]');
  }
  function value(i) {
    if (!i) return null;
    return (i.value !== undefined ? i.value : (i.textContent || ''));
  }
  function hide() {
    if (mode() !== 'shown') return;
    // 2026-09-21：手动点右下角开关后 1.5 秒内不要自动收起，否则会和手动切换打架
    // （实测：手动收起后它会把输入框又弹回来）
    if (Date.now() - (window.__dshManualToggleAt || 0) < 1500) return;
    var dot = document.getElementById('dsh-composer-dot');
    if (dot) dot.click();          // 复用右下角小圆点的切换
  }
  setInterval(function () {
    if (mode() !== 'shown') { last = null; return; }
    var i = input();
    if (!i) return;
    var v = value(i);
    if (last !== null && last.trim() !== '' && (v || '').trim() === '') {
      setTimeout(hide, 350);      // 刚被清空 → 判定为已发送，稍等一拍再收起
    }
    last = v;
  }, 250);
})();

keep:
(function () {
  // 2026-09-21：右下角只留这一个常驻圆钮（原生「回到底部」已被 CSS 隐藏）。
  // 语义按场景走：往上翻着 → 回到底部（顺手展开输入框）；已在底部 → 开关输入框。
  // ⚠️ 不要给它 aria-label=回到底部 —— 会命中 dsh-composer-script 的委托，把刚收起的输入框又弹开。
  function seat() { return document.querySelector('.wSkVaW_composerSeat'); }
  function scroller() { return document.querySelector('.wSkVaW_scrollBody'); }
  function hidden() { return document.documentElement.getAttribute('data-dsh-composer') === 'hidden'; }
  function dot() { return document.getElementById('dsh-composer-dot'); }
  function scrollBottom() { var sc = scroller(); if (sc) { try { sc.scrollTop = sc.scrollHeight; } catch (e) {} } }
  function atBottom() {
    var sc = scroller();
    if (!sc) return true;
    try { return sc.scrollTop + sc.clientHeight >= sc.scrollHeight - 8; } catch (e) { return true; }
  }
  function apply() {
    var b = document.getElementById('dsh-tobottom-keep');
    if (!b) return;
    var h = 0, s = seat();
    if (!hidden() && s) { try { h = s.getBoundingClientRect().height || 0; } catch (e) {} }
    b.style.bottom = (h ? h + 10 : 10) + 'px';
    var up = !atBottom();
    var svg = b.querySelector('svg');
    if (svg) svg.style.transform = (up || !hidden()) ? 'none' : 'rotate(180deg)';
    b.title = up ? '回到底部' : (hidden() ? '显示输入框' : '隐藏输入框');
  }
  function scrollBottomHard() {                     // 布局变化时补滚一小段时间（实测单次会被顶回去）
    var end = Date.now() + 1500;
    (function loop() {
      scrollBottom();
      if (Date.now() < end && !atBottom()) setTimeout(loop, 150);
    })();
  }
  function onTap() {
    window.__dshManualToggleAt = Date.now();       // 让 autohide 脚本 1.5s 内别插手
    if (!atBottom()) {                             // 往上翻着 → 只做"回到底部"，不动输入框
      scrollBottomHard();
    } else {                                       // 已在底部 → 开关输入框
      var wasHidden = hidden();
      var d = dot(); if (d) d.click();
      if (wasHidden) scrollBottomHard();           // 展开会占掉高度，补滚
    }
    setTimeout(apply, 80);
  }
  function boot() {
    if (document.getElementById('dsh-tobottom-keep')) { apply(); return; }
    var b = document.createElement('button');
    b.id = 'dsh-tobottom-keep';
    b.type = 'button';
    b.setAttribute('aria-label', '输入框与滚动开关');
    b.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"></path></svg>';
    b.addEventListener('click', onTap);
    document.body.appendChild(b);
    apply();
    document.addEventListener('scroll', apply, true);   // 滚动位置变了就更新图标方向
    new MutationObserver(apply).observe(document.body, { subtree: true, attributes: true, attributeFilter: ['style', 'class'] });
    setInterval(apply, 700);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot();
})();
